"""Traductions anglaise et arabe de l'article « Son ascendance » (même ordre que CORPS dans ascendance.py)."""
import os, html

PHOTOS = {
 "idriss-i": "moulay-idriss-al-akbar", "idriss-ii": "moulay-idriss-al-azhar", "mimoun": "moulay-mimoun",
 "mkhoukh": "sidi-mkhoukh", "ali-moussa": "sidi-ali-ibn-moussa",
}
def photo(cle, legende):
    f = "public/shaykh/ascendance/%s.webp" % PHOTOS[cle]
    img = '<img src="/shaykh/ascendance/%s.webp" alt="%s" loading="lazy" decoding="async" />' % (PHOTOS[cle], html.escape(legende, quote=True)) if os.path.exists(f) else ""
    return '<figure class="asc-photo">%s<figcaption>%s</figcaption></figure>' % (img, legende)
def hadiths(*items): return '<ul class="hadiths">' + "".join("<li>%s</li>" % i for i in items) + "</ul>"
def p(t): return "<p>%s</p>" % t

EN = [
 p("The most illustrious of his forefathers is, of course, the master of the two worlds, the chief of the children of Adam, the bearer of the banner of praise, our master Muhammad ﷺ, upon him be Allah's peace and blessings, and upon his family and companions."),
 p("Among his children was our illustrious mother, the pure, pious and virtuous Sayyida Fatima al-Zahra, whom her father ﷺ named among the four best women of Paradise, alongside Sayyida Maryam, Sayyida Asiya and Sayyida Khadija, may Allah have mercy on them. Concerning her, the Prophet ﷺ said:"),
 hadiths("“Fatima is a part of me. Whoever angers her angers me.”", "“Allah is angered by what angers you, and He is pleased by what pleases you.”"),
 p("She married Sayiduna ‘Ali Ibn Abi Talib, the Prophet's cousin, the child who was born inside the Kaaba, who never worshipped an idol, the first child to embrace Islam, and who became a major figure of the first Muslim community. Concerning him, the Prophet ﷺ said:"),
 hadiths("“Are you not pleased to be to me what Aaron was to Moses, except that there will be no prophet after me?”", "“I am the city of knowledge and ‘Ali is its gate.”", "“Whoever I am his master, ‘Ali is his master. O Allah, support those who support ‘Ali, and be the enemy of those who become the enemies of ‘Ali.”"),
 p("After the assassination of the caliph ‘Uthman Ibn ‘Affan by a group of rebels, Sayiduna ‘Ali Ibn Abi Talib was chosen as the fourth caliph and received the allegiance of a large part of the Muslims, with the exception of the companion Mu‘awiya Ibn Abi Sufyan, then governor of Syria, Palestine and Egypt. A close relative of ‘Uthman, he refused to pledge allegiance to Sayiduna ‘Ali as long as those responsible for ‘Uthman's murder had not been brought to justice. This disagreement led to several major conflicts, up to the assassination of Sayiduna ‘Ali Ibn Abi Talib in his mosque in Kufa in 661."),
 p("He left several children, among them the masters of the youth of Paradise, Sayiduna al-Hassan and Sayiduna al-Hussein. Their names were chosen by the Prophet ﷺ himself, who said of them:"),
 hadiths("“Whoever loves al-Hassan and al-Hussein loves me, and whoever hates them hates me.”", "“These are my grandsons, the sons of my daughter. O Lord, I love them. Love them, and love those who love them.”"),
 p("The forefather of Sidi Mohamed Faouzi al-Karkari, Sayiduna al-Hassan Ibn ‘Ali (624-670), was also the subject of a prophecy by his noble grandfather ﷺ which came true. He had said of him:"),
 hadiths("“This son of mine is a master (sayyid), and through him Allah will reconcile two great groups of Muslims.”"),
 p("This is what happened in the year 40 of the Hijra. After the tragic assassination of Sayiduna ‘Ali Ibn Abi Talib, Sayiduna al-Hassan Ibn ‘Ali was recognised as the fifth caliph of the Muslims. However, the companion Mu’awiya Ibn Abi Sufyan, who still governed the regions of Syria, Palestine and Egypt, again refused to pledge allegiance to him."),
 p("Concerned to preserve the unity of the Muslims, and fearing that a war with Mu’awiya would bring bloodshed within their ranks, Sayiduna al-Hassan chose to give up power six months after his accession to the caliphate, in favour of Mu’awiya. That year would go down in history as the “year of unity”, marking the beginning of the rule of the Umayyad dynasty."),
 p("Following this agreement, a group of Muslim dissidents declared his excommunication from the Muslim community, considering that giving up the caliphate was an act of disbelief. Sayiduna al-Hassan escaped several assassination attempts, but was finally poisoned and died from the poison."),
 p("Among his many children was the great scholar Sayiduna al-Hassan al-Muthanna (661-715). He was present at the infamous battle of Karbala (680), alongside his uncle Sayiduna al-Hussein Ibn ‘Ali, a battle in which al-Hussein's family was massacred and he himself was beheaded by the Umayyads. Al-Hassan al-Muthanna was then only nineteen. He was wounded and captured, but managed to survive. He later married his cousin Fatima bint al-Hussein Ibn ‘Ali, one of the survivors of that battle. Several children were born of this union, among them the forefather of Shaykh Mohamed Faouzi al-Karkari, Sayiduna Abdallah al-Kamil."),
 p("The latter played a very important role in his time. He was a man known for his piety, anxious to preserve the heritage of the Ahl al-Bayt. He was nicknamed “al-Kamil”, that is “the Complete”, because he was a descendant of al-Hassan Ibn ‘Ali through his father and of al-Hussein Ibn ‘Ali through his mother, thus uniting the two noble sharifian lines."),
 p("Living under the Umayyad dynasty, he was a major political figure. He was the leader of the descendants of al-Hassan Ibn ‘Ali in Medina, at a time when many wished to see the family of the Prophet ﷺ lead the Muslims. To overthrow the Umayyads, Abdallah al-Kamil made a pact with many groups of Muslims, among them the descendants of the Prophet's uncle al-Abbas, known as the Abbasids. This pact provided that when the Umayyads fell, power would go to his son Mohamed Nafs-zakiya, to whom all pledged allegiance."),
 p("Unfortunately, once they had managed to overthrow the Umayyads, the Abbasids went back on their pledges and seized power. They then turned against the descendants of the Prophet ﷺ, whom they now regarded as dangerous rivals in the quest for power. The Abbasid caliph al-Mansur asked Sayiduna Abdallah al-Kamil to pledge allegiance to him; he refused and was imprisoned until his death."),
 p("His family and children, among them Mohamed Nafs-zakiya, Ibrahim, Sulayman and Moulay Idriss, were harshly repressed. They then led several revolts against the Abbasids, the best known being the battle of Fakhkh in 786. This revolt would become, in a way, a second massacre of the Prophet's descendants after that of Karbala."),
 p("Historians estimate that between one hundred and four hundred members of the Prophet's family ﷺ were killed that day. Several people nevertheless managed to escape, notably the noble and pious Moulay Idriss, forefather of Shaykh Mohamed Faouzi al-Karkari, who was then hunted by the caliph, who wished to eliminate any threat to his power."),
 "<h3>An Idrisid ancestry</h3>",
 photo("idriss-i", "Mausoleum of Moulay Idriss al-Akbar, known as “Moulay Idriss I”, in the village of Moulay Idriss Zerhoun near the city of Meknes."),
 p("Faced with repression by the Abbasid caliphate, Moulay Idriss left the Hijaz and began a long exile. He first went to Egypt, but pursuit by the Abbasid authorities forced him to flee to Ifriqiya (present-day Tunisia), then to the far western end of the Muslim world. He found refuge among the Amazigh tribes of present-day Morocco, more precisely in the ancient Roman city of Volubilis, in the Meknes region."),
 p("These tribes gave him a favourable welcome and honoured him, out of the deep respect they held for the descendants of the Prophet Muhammad ﷺ. They gathered around him and recognised his authority. He then married Lalla Kenza, of the Awraba tribe, and this union marked the emergence of the Idrisid dynasty, the first Muslim dynasty of Morocco."),
 p("It was through this exile of Moulay Idriss that, over the centuries, the descendants and heirs of the Prophet ﷺ would settle North Africa in great numbers. However, the Abbasid caliph Harun ar-Rashid, fearing the emergence of a rival power that might weaken his authority, pursued his aim of eliminating Moulay Idriss. Knowing that he was under the protection of the Amazigh tribes, the caliph therefore commissioned an infiltrated agent who posed as a fugitive and who finally assassinated him in the year 790."),
 p("In Baghdad, the Abbasid caliph considered that he had put an end to the Idrisid threat. He thought he had extinguished this line, but he did not know that at the time of Moulay Idriss's assassination, his wife was already pregnant with his heir. Thus, a few months later, was born the son of Moulay Idriss and heir to the Idrisid throne, Moulay Idriss II, known as “al-Azhar”."),
 p("Raised in the greatest secrecy, Moulay Idriss al-Azhar came to the throne at the age of eleven. Renowned for his piety, knowledge and intelligence, he played a central role in organising the territory and founded the city of Fez at the beginning of the ninth century. He was in fact its architect, since it was he who conceived the medina of Fez with its countless lanes that mingle and cross. His aim was to throw off course anyone who might attempt to take his life."),
 photo("idriss-ii", "Mausoleum of Moulay Idriss al-Azhar, known as “Moulay Idriss II”, located in his zawiya in the heart of the medina of Fez, near the al-Qarawiyyin University."),
 p("Moulay Idriss al-Azhar then consolidated his father's kingdom through alliances with various Amazigh tribes. After his death in 828, he left a vast unified territory and numerous descendants, some fifteen children, among them twelve sons."),
 p("His son Mohamed Ibn Idriss succeeded him, but his accession to power was soon followed by the first internal tensions with his brothers. They too were seeking power, and to avoid conflict Mohamed Ibn Idriss decided to follow the advice of his grandmother Lalla Kenza. He divided his kingdom into eleven provinces, which were entrusted to his brothers as governors."),
 p("Among them was the forefather of Sidi Mohamed Faouzi al-Karkari, Moulay al-Qassim Ibn Idriss, who left Fez to settle in the western Rif, a region he administered from Tangier to Larache and as far as the surroundings of present-day al-Hoceima. In a context of growing internal tensions, a fratricidal war eventually broke out between Mohamed Ibn Idriss and his brothers. Moulay al-Qassim, known for his asceticism and piety, refused to take part in the conflict despite the orders of his brother, the ruler of the Idrisids, Mohamed Ibn Idriss. Moulay al-Qassim then decided to withdraw from power around 840 and settled in a ribat in the region of Asilah, where he would end his days in 860 in devotion and asceticism."),
 p("His son Mohamed Ibn al-Qassim Ibn Idriss, nicknamed Mohamed al-Bakmani, immediately succeeded his father, in a context of gradual weakening of the central power in Fez. He nevertheless managed to maintain Idrisid authority in the western Rif. He had several children, among them the forefather of Shaykh Mohamed Faouzi al-Karkari, Ahmad Ibn Mohamed, known as Ahmad Belkarti."),
 p("Nicknamed “Janun”, which means “the moon” in Amazigh, he shared control of the northern and western regions of Morocco with his brothers Ibrahim and al-Qassim Ibn Mohamed Ibn al-Qassim Ibn Idriss, in a context marked by increasingly frequent Fatimid and Umayyad incursions. He died around the year 920 and left several children, among them Moulay ‘Iyyad, a local governor in the region of Ksar al-Kebir. Faced with ever stronger external threats, he helped maintain Idrisid power, but he eventually withdrew to the mountainous areas of the Rif."),
 p("Moulay ‘Iyyad died around 960, leaving among his children the forefather of Shaykh Mohamed Faouzi al-Karkari, Moulay Salem Ibn ‘Iyyad, who would witness the gradual fall of the Idrisid dynasty. Moulay Salem is often cited as one of the major ancestors of many sharifs of northern Morocco, such as Sidi ‘Abd as-Salam Ibn Machich. He was one of the turning points between the princely Idrisids, involved in local politics and power games, and the rural Idrisids, who abandoned politics to blend into the mountains of the Rif."),
 p("Moulay Salem Ibn ‘Iyyad turned to spirituality and religious teaching among the Jbala tribes, and he had numerous descendants, figures known and recognised for their piety and wisdom."),
 p("Between the eleventh and fifteenth centuries, the blessed lineage of Shaykh Mohamed Faouzi al-Karkari continued after Moulay Salem Ibn ‘Iyyad, whose son was Moulay ‘Imrane, whose son was Moulay Jaber, whose son was Moulay ‘Alal, whose son was Moulay ‘Abd al-‘Aziz, whose son was Moulay Me’zouz, whose son was Moulay ‘Azouz, whose son was Moulay Moussa, whose son was Moulay ‘Issa, whose son was Moulay Mess’oud, whose son was Moulay Mimoun Abu Wakil, also called Boukil Ibn Mess’oud al-Idrissi, founder of the Bani Wakil tribe. The name of Sidi Mohamed Ibn al-Qaddur al-Wakili, also called “al-Boukili”, comes from him."),
 photo("mimoun", "Mausoleum of Sidi Mimoun Abu Wakil, known as “Boukil”, in the village of Zaouiat Sidi Boukil, near the city of Errachidia, in the Tafilalet region."),
 p("After him, the Bani Wakil tribe divided into four groups of Idrisid sharifs: the Ankad group, the Trifa group, the Bani Wakil al-Mawakhikh group, which take their name from the forefather of Sidi Mohamed Faouzi al-Karkari and son of Moulay Mimoun Abu Wakil, Sidi Mkhoukh, and the Ouled Sidi Moussa group."),
 p("Sidi Mimoun Abu Wakil was born in the year 442 of the Hijra, corresponding to 1050 CE, in the Middle Atlas region near the present-day town of Tadla, where his forefather Moulay ‘Imrane Ibn Salem had emigrated. He grew up in an age of tribal wars and unrest pitting the Fatimids against the Amazigh chief Moussa Ibn Abi al-Afia al-Miknassi. The latter governed central Morocco until the advent of Sultan Youssef Ibn Tachfine, founder of the capital Marrakech and father of the Almoravid dynasty."),
 p("Around 1096, Sidi Mimoun Abu Wakil and his brother ‘Abd ar-Rahman set out to perform the pilgrimage (Hajj). There they met the Imam Abu Hamid al-Ghazali, who became their Shaykh. For several years they remained in his company and benefited from his teachings, until the death of Sidi ‘Abd ar-Rahman in Medina. Sidi Mimoun Abu Wakil returned to Morocco at the time of the first uprisings of the Almohads, led by Mohamed Ibn Tumert, against Almoravid rule."),
 p("Sidi Mimoun married his cousin, with whom he had five children, and after his death he was buried near Errachidia, in the small village of Zaouiat Sidi Boukil, where his mausoleum stands. It should be noted here that the family trees of Shaykh Sidi Mohamed Faouzi al-Karkari and of his wife Lalla Najat meet at Sidi Mimoun."),
 p("Among his children was Sidi ‘Issa Ibn Mimoun, forefather of Sidi Mohamed Faouzi al-Karkari, who is known and mentioned in several works under the name of Sidi Makhoukh. He grew up in the village of Ighejd in the province of Errachidia in the eleventh century, then settled near Oujda in the town of El Aïoun Sidi Mellouk. It is there that he died, having left his mark on local memory. A mausoleum was built over his grave and many public buildings in the town bear his name today."),
 photo("mkhoukh", "Mausoleum of Sidi Makhoukh, in the Oriental region, in the town of El Aïoun Sidi Mellouk."),
 p("He had several children, among them Sidi ‘Ali Ibn ‘Issa, whose son was Moulay Mohamed, whose son was Moulay al-Hassan, whose son was Moulay ‘Issa, whose son was Moulay Yahya, whose son was Moulay Zakariya, whose son was Moulay ‘Abd al-‘Aziz, whose son was Moulay Abdallah, whose son was Moulay ‘Abd ar-Rahman, whose son was Moulay Yahya, whose son was Moulay Ibn Zayd, whose son was Moulay Ibrahim, whose son was Moulay Ya’qub, whose son was Moulay ‘Ali, whose son was Moulay Moussa, whose son was Moulay ‘Ali, on whom we shall pause for a moment."),
 p("Indeed, Sidi ‘Ali Ibn Moussa was an educator Shaykh who lived in the sixteenth century under the Saadian dynasty. He is notably known for having taken part in one of the most famous battles in Moroccan history: the celebrated Battle of the Three Kings. It took place in 1578 and pitted the Saadian Sultan ‘Abd al-Malik, accompanied by his brother, the future Sultan Ahmad al-Mansur adh-Dhahabi, against King Sebastian I of Portugal, supported by the former deposed sultan al-Moutawakil."),
 photo("ali-moussa", "Mausoleum of Sidi ‘Ali ibn Moussa, in the eastern Rif region, in the town of al-Aroui."),
 p("At the end of this battle, Sultan ‘Abd al-Malik's army won a total victory, leading to the death of King Sebastian I and of the traitor sultan al-Moutawakil. This victory brought about the end of the ruling dynasty in Portugal and the annexation of the country by the Spanish crown. Sidi ‘Ali Ibn Moussa was able to return to his home region, more precisely al-Aroui, where he was in fact buried. His mausoleum stands beside that of his father, Sidi Moussa Ibn ‘Ali, in the cemetery that bears his name at the entrance to the town."),
 p("Since the sixteenth century, twelve forefathers of Shaykh Mohamed Faouzi al-Karkari have thus been buried in the eastern Rif region, between al-Aroui and Tamsamane. Their domed mausoleums bear witness to the rootedness of this lineage in the region. Many of them were scholars of Islamic jurisprudence, but also knowers through Allah and guides on the path of spiritual realisation."),
 p("Sidi ‘Ali Ibn Moussa's son was Moulay Mohamed, whose son was Moulay al-‘Arbi, whose son was Moulay Ahmad, whose son was Moulay ‘Abd al-Qadir, whose son was the Shaykh and Pole of his time Sidi Mohamed Ibn al-Qaddur al-Boukili, fifth forefather of Shaykh Mohamed Faouzi al-Karkari."),
]

AR = [
 p("وأشرف أجداده بلا ريب سيّد الكونين وسيّد ولد آدم وصاحب لواء الحمد، سيّدنا محمد ﷺ، عليه من الله الصلاة والسلام، وعلى آله وصحبه."),
 p("ومن أولاده أمّنا الجليلة الطاهرة التقية الفاضلة السيدة فاطمة الزهراء، التي جعلها أبوها ﷺ إحدى أفضل أربع نساء في الجنة، مع السيدة مريم والسيدة آسية والسيدة خديجة، رحمهنّ الله. وقال فيها النبي ﷺ:"),
 hadiths("«فاطمة بضعة مني، فمن أغضبها أغضبني.»", "«إن الله يغضب لغضبك ويرضى لرضاك.»"),
 p("تزوجت سيدنا علي بن أبي طالب، ابن عمّ النبي ﷺ، المولود في الكعبة، الذي لم يعبد صنمًا قط، وأول الصبيان إسلامًا، وصار من كبار رجالات الأمة الإسلامية الأولى. وقال فيه النبي ﷺ:"),
 hadiths("«أما ترضى أن تكون مني بمنزلة هارون من موسى إلا أنه لا نبي بعدي؟»", "«أنا مدينة العلم وعلي بابها.»", "«من كنت مولاه فعلي مولاه، اللهم وال من والاه وعاد من عاداه.»"),
 p("بعد مقتل الخليفة عثمان بن عفان على يد جماعة من الثائرين، اختير سيدنا علي بن أبي طالب خليفةً رابعًا، وبايعه جلّ المسلمين، ما عدا الصحابي معاوية بن أبي سفيان، والي الشام وفلسطين ومصر آنذاك. وكان معاوية قريبًا من عثمان، فامتنع عن مبايعة سيدنا علي ما لم يُحاكَم قتلة عثمان. وقاد هذا الخلاف إلى عدة نزاعات كبرى، إلى أن اغتيل سيدنا علي بن أبي طالب في مسجده بالكوفة سنة 661م."),
 p("وخلّف عدة أولاد، منهم سيّدا شباب أهل الجنة سيدنا الحسن وسيدنا الحسين. وقد اختار لهما النبي ﷺ اسميهما بنفسه، وقال فيهما:"),
 hadiths("«من أحب الحسن والحسين فقد أحبني، ومن أبغضهما فقد أبغضني.»", "«هذان ابناي وابنا ابنتي، اللهم إني أحبهما فأحبهما وأحب من يحبهما.»"),
 p("وكان جدّ سيدي محمد فوزي الكركري، سيدنا الحسن بن علي (624-670م)، موضوع نبوءةٍ لجدّه الكريم ﷺ تحققت. فقد قال فيه:"),
 hadiths("«إن ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين.»"),
 p("وهذا ما وقع سنة 40 للهجرة. فبعد الاغتيال المأساوي لسيدنا علي بن أبي طالب، بويع سيدنا الحسن بن علي خليفةً خامسًا للمسلمين. غير أن الصحابي معاوية بن أبي سفيان، الذي كان لا يزال يحكم الشام وفلسطين ومصر، امتنع مرة أخرى عن مبايعته."),
 p("وحرصًا منه على وحدة المسلمين، وخشيةَ أن تُسفر حربٌ مع معاوية عن إراقة دماء في صفوفهم، اختار سيدنا الحسن أن يتنازل عن الحكم بعد ستة أشهر من توليه الخلافة لمعاوية. وسيبقى ذلك العام في التاريخ باسم «عام الجماعة»، ومعه بدأ حكم الدولة الأموية."),
 p("وإثر هذا الاتفاق، أعلنت جماعة من المسلمين المنشقين إخراجه من جماعة المسلمين، معتبرةً أن التنازل عن الخلافة فعلُ كفر. ونجا سيدنا الحسن من عدة محاولات اغتيال، لكنه سُمّ في النهاية ومات بالسم."),
 p("ومن بين أولاده الكثيرين العالم الجليل سيدنا الحسن المثنى (661-715م). وقد شهد معركة كربلاء المشؤومة (680م) إلى جانب عمّه سيدنا الحسين بن علي، المعركة التي أُبيدت فيها أسرة الحسين وقُطع رأسه على يد الأمويين. وكان الحسن المثنى حينها في التاسعة عشرة. جُرح وأُسر، لكنه نجا. ثم تزوج ابنة عمّه فاطمة بنت الحسين بن علي، إحدى الناجيات من تلك المعركة. وُلد لهما عدة أبناء، منهم جدّ الشيخ محمد فوزي الكركري سيدنا عبد الله الكامل."),
 p("وقد أدّى هذا الأخير دورًا بالغ الأهمية في عصره. كان رجلًا معروفًا بتقواه، حريصًا على صون تراث آل البيت. ولُقّب بـ«الكامل» لأنه ينتسب إلى الحسن بن علي من جهة أبيه وإلى الحسين بن علي من جهة أمه، فجمع بذلك بين النسبين الشريفين."),
 p("وعاش في ظل الدولة الأموية وكان شخصية سياسية بارزة؛ فهو زعيم أحفاد الحسن بن علي في المدينة المنورة، في زمن كان كثيرون يتطلعون فيه إلى أن تقود أسرة النبي ﷺ المسلمين. ومن أجل إسقاط الأمويين، عقد عبد الله الكامل حلفًا مع جماعات كثيرة من المسلمين، منهم أحفاد عمّ النبي العباس، المعروفون بالعباسيين. ونصّ هذا الحلف على أن يؤول الحكم عند سقوط الأمويين إلى ابنه محمد النفس الزكية، الذي بايعه الجميع."),
 p("ولكن، بعد أن نجحوا في إسقاط الأمويين، نقض العباسيون بيعتهم واستولوا على الحكم. ثم انقلبوا على ذرية النبي ﷺ التي صاروا يرونها منافسًا خطيرًا في الصراع على السلطة. وطلب الخليفة العباسي المنصور من سيدنا عبد الله الكامل أن يبايعه، فرفض، فسُجن حتى وفاته."),
 p("وتعرّضت أسرته وأبناؤه، ومنهم محمد النفس الزكية وإبراهيم وسليمان ومولاي إدريس، لقمعٍ شديد. فقادوا عدة ثورات ضد العباسيين، أشهرها معركة فخّ سنة 786م. وستكون هذه الثورة بمثابة مجزرة ثانية بحق ذرية النبي بعد مجزرة كربلاء."),
 p("ويقدّر المؤرخون عدد من قُتل من أسرة النبي ﷺ ذلك اليوم بين مئة وأربعمئة. غير أن عددًا منهم تمكن من الفرار، لا سيما مولاي إدريس الشريف التقي، جدّ الشيخ محمد فوزي الكركري، الذي تعقّبه الخليفة بعد ذلك رغبةً في القضاء على كل ما يهدد سلطانه."),
 "<h3>أصلٌ إدريسي</h3>",
 photo("idriss-i", "ضريح مولاي إدريس الأكبر المعروف بـ«مولاي إدريس الأول»، في قرية مولاي إدريس زرهون قرب مدينة مكناس."),
 p("وأمام قمع الخلافة العباسية، غادر مولاي إدريس الحجاز وبدأ منفىً طويلًا. توجه أولًا إلى مصر، لكن ملاحقة السلطات العباسية اضطرّته إلى الفرار نحو إفريقية (تونس الحالية)، ثم إلى أقصى غرب العالم الإسلامي. ووجد ملاذًا لدى القبائل الأمازيغية في المغرب الحالي، وتحديدًا في مدينة وليلي الرومانية القديمة بمنطقة مكناس."),
 p("وقد استقبلته هذه القبائل استقبالًا حسنًا وأكرمته لما كانت تكنّه من احترام عميق لذرية النبي محمد ﷺ. فالتفّت حوله وأقرّت بسلطانه. ثم تزوج لالة كنزة من قبيلة أوربة، وكان هذا الزواج إيذانًا بقيام الدولة الإدريسية، أول دولة إسلامية في المغرب."),
 p("ومن خلال منفى مولاي إدريس هذا، سيستقر أحفاد النبي ﷺ وورثته، على مرّ القرون، في شمال إفريقيا بأعداد كبيرة. غير أن الخليفة العباسي هارون الرشيد، خشيةَ قيام سلطة منافسة قد تُضعف سلطانه، مضى في سعيه للقضاء على مولاي إدريس. ولأنه كان في حماية القبائل الأمازيغية، كلّف الخليفة عميلًا متسلّلًا تظاهر بأنه فارّ، فتمكن في النهاية من اغتياله سنة 790م."),
 p("وفي بغداد، رأى الخليفة العباسي أنه قضى على الخطر الإدريسي. وظنّ أنه أطفأ هذه السلالة، ولم يكن يعلم أن زوجة مولاي إدريس كانت حاملًا بوريثه وقت اغتياله. وهكذا وُلد بعد أشهر قليلة ابن مولاي إدريس ووريث عرشه، مولاي إدريس الثاني المعروف بـ«الأزهر»."),
 p("نشأ مولاي إدريس الأزهر في كتمانٍ شديد، وتولى العرش وهو في الحادية عشرة. وعُرف بتقواه وعلمه وذكائه، وأدّى دورًا محوريًا في تنظيم البلاد، وأسّس مدينة فاس مطلع القرن التاسع الميلادي. وهو في الحقيقة مهندسها، فهو الذي تصوّر مدينة فاس العتيقة بأزقتها التي لا تُحصى وهي تتداخل وتتقاطع. وكان هدفه إرباك كل من يحاول النيل من حياته."),
 photo("idriss-ii", "ضريح مولاي إدريس الأزهر المعروف بـ«مولاي إدريس الثاني»، في زاويته وسط مدينة فاس العتيقة، قرب جامعة القرويين."),
 p("ثم عمل مولاي إدريس الأزهر على توطيد مملكة أبيه بتحالفات مع مختلف القبائل الأمازيغية. وبعد وفاته سنة 828م ترك أرضًا واسعة موحَّدة وذرية كثيرة تضم نحو خمسة عشر ولدًا منهم اثنا عشر ذكرًا."),
 p("وخلفه ابنه محمد بن إدريس، لكن توليه الحكم أعقبته سريعًا أولى التوترات الداخلية مع إخوته. فقد كانوا هم أيضًا يطلبون الحكم، ولتفادي النزاع قرّر محمد بن إدريس أن يأخذ بنصيحة جدّته لالة كنزة. فقسّم مملكته إلى إحدى عشرة ولاية أُسندت إلى إخوته ولاةً عليها."),
 p("ومن بينهم جدّ سيدي محمد فوزي الكركري، مولاي القاسم بن إدريس، الذي غادر فاس واستقر في الريف الغربي، وهي منطقة أدارها من طنجة إلى العرائش وحتى ضواحي مدينة الحسيمة الحالية. وفي ظل تزايد التوترات الداخلية، اندلعت في النهاية حربٌ بين الإخوة، بين محمد بن إدريس وإخوته. أما مولاي القاسم، المعروف بزهده وتقواه، فرفض المشاركة في النزاع رغم أوامر أخيه وحاكم الأدارسة محمد بن إدريس. فقرر مولاي القاسم الانسحاب من الحكم نحو سنة 840، واستقر في رباط بمنطقة أصيلة حيث قضى بقية حياته في العبادة والزهد إلى أن توفي سنة 860م."),
 p("وخلفه ابنه محمد بن القاسم بن إدريس، الملقب بمحمد البكماني، في سياق ضعف تدريجي للسلطة المركزية في فاس. ومع ذلك تمكن من الحفاظ على السلطة الإدريسية في الريف الغربي. وأنجب في تلك الفترة عدة أبناء، منهم جدّ الشيخ محمد فوزي الكركري، أحمد بن محمد المعروف بأحمد بلكارتي."),
 p("وكان يُلقَّب بـ«جنون»، أي «القمر» بالأمازيغية. واقتسم السيطرة على مناطق شمال المغرب وغربه مع أخويه إبراهيم والقاسم ابني محمد بن القاسم بن إدريس، في سياق تتكرر فيه الغارات الفاطمية والأموية. وتوفي نحو سنة 920 وخلّف عدة أبناء، منهم مولاي عياض، وهو حاكم محلي في منطقة القصر الكبير. وأمام التهديدات الخارجية المتزايدة، أسهم في الحفاظ على السلطة الإدريسية، لكنه انتهى به الأمر إلى الانكفاء نحو المناطق الجبلية بالريف."),
 p("وتوفي مولاي عياض نحو سنة 960، تاركًا من بين أبنائه جدّ الشيخ محمد فوزي الكركري، مولاي سالم بن عياض، الذي سيشهد السقوط التدريجي للدولة الإدريسية. ويُذكر مولاي سالم كثيرًا بوصفه أحد الأجداد الكبار لعدد من أشراف شمال المغرب، مثل سيدي عبد السلام بن مشيش. وكان أحد نقاط التحول بين الأدارسة الأمراء المنخرطين في السياسة المحلية وصراعات السلطة، والأدارسة القرويين الذين تركوا السياسة وذابوا في جبال الريف."),
 p("واتجه مولاي سالم بن عياض إلى الروحانية والتعليم الديني في قبائل جبالة، وكانت له ذرية كثيرة من شخصيات معروفة بتقواها وحكمتها."),
 p("وبين القرنين الحادي عشر والخامس عشر، امتد النسب المبارك للشيخ محمد فوزي الكركري بعد مولاي سالم بن عياض، الذي ولد مولاي عمران، الذي ولد مولاي جابر، الذي ولد مولاي علال، الذي ولد مولاي عبد العزيز، الذي ولد مولاي معزوز، الذي ولد مولاي عزوز، الذي ولد مولاي موسى، الذي ولد مولاي عيسى، الذي ولد مولاي مسعود، الذي ولد مولاي ميمون أبا وكيل المسمى أيضًا بوكيل بن مسعود الإدريسي، مؤسس قبيلة بني وكيل. ومنه جاء اسم سيدي محمد بن القدور الوكيلي، المسمى أيضًا «البوكيلي»."),
 photo("mimoun", "ضريح سيدي ميمون أبي وكيل المعروف بـ«بوكيل»، في قرية زاوية سيدي بوكيل قرب مدينة الرشيدية، بمنطقة تافيلالت."),
 p("وبعده انقسمت قبيلة بني وكيل إلى أربع مجموعات من الأشراف الأدارسة: مجموعة أنكاد، ومجموعة تريفة، ومجموعة بني وكيل المواخيخ التي تأخذ اسمها من جدّ سيدي محمد فوزي الكركري وابن مولاي ميمون أبي وكيل، سيدي مخوخ، ومجموعة أولاد سيدي موسى."),
 p("وُلد سيدي ميمون أبو وكيل سنة 442 للهجرة الموافقة لسنة 1050م في منطقة الأطلس المتوسط قرب مدينة تادلة الحالية، حيث هاجر جدّه مولاي عمران بن سالم. ونشأ في زمن حروب قبلية واضطرابات بين الفاطميين والزعيم الأمازيغي موسى بن أبي العافية المكناسي. وقد حكم هذا الأخير منطقة وسط المغرب إلى أن ظهر السلطان يوسف بن تاشفين، مؤسس عاصمته مراكش وأبو الدولة المرابطية."),
 p("ونحو سنة 1096، انطلق سيدي ميمون أبو وكيل وأخوه عبد الرحمن لأداء فريضة الحج. وهناك التقيا الإمام أبا حامد الغزالي الذي صار شيخهما. وبقيا في صحبته سنوات عدة ينتفعان بتعاليمه إلى أن توفي سيدي عبد الرحمن بالمدينة المنورة. وعاد سيدي ميمون أبو وكيل إلى المغرب، في زمن أولى ثورات الموحدين بقيادة محمد بن تومرت ضد حكم المرابطين."),
 p("وتزوج سيدي ميمون ابنة عمّه فأنجب منها خمسة أبناء، وبعد وفاته دُفن قرب الرشيدية في قرية زاوية سيدي بوكيل الصغيرة، حيث يوجد ضريحه. ومن الجدير بالذكر هنا أن شجرتي نسب الشيخ سيدي محمد فوزي الكركري وزوجته لالة نجاة تلتقيان عند سيدي ميمون."),
 p("ومن أبنائه سيدي عيسى بن ميمون، جدّ سيدي محمد فوزي الكركري، المعروف والمذكور في عدة مؤلفات باسم سيدي مخوخ. نشأ في قرية إيغجد بإقليم الرشيدية في القرن الحادي عشر، ثم استقر قرب وجدة في مدينة العيون سيدي ملوك. وفيها توفي بعد أن ترك أثرًا في الذاكرة المحلية. وشُيّد ضريح على قبره، وتحمل اليوم اسمَه عدة مبانٍ عمومية في المدينة."),
 photo("mkhoukh", "ضريح سيدي مخوخ، في جهة الشرق، بمدينة العيون سيدي ملوك."),
 p("وكان له عدة أبناء، منهم سيدي علي بن عيسى الذي ولد مولاي محمد، الذي ولد مولاي الحسن، الذي ولد مولاي عيسى، الذي ولد مولاي يحيى، الذي ولد مولاي زكريا، الذي ولد مولاي عبد العزيز، الذي ولد مولاي عبد الله، الذي ولد مولاي عبد الرحمن، الذي ولد مولاي يحيى، الذي ولد مولاي ابن زيد، الذي ولد مولاي إبراهيم، الذي ولد مولاي يعقوب، الذي ولد مولاي علي، الذي ولد مولاي موسى، الذي ولد مولاي علي، الذي سنقف عنده قليلًا."),
 p("فقد كان سيدي علي بن موسى شيخًا مربّيًا عاش في القرن السادس عشر في ظل الدولة السعدية. ويُعرف خصوصًا بمشاركته في إحدى أشهر المعارك في تاريخ المغرب: معركة الملوك الثلاثة الشهيرة. جرت سنة 1578 وواجه فيها السلطان السعدي عبد الملك، ومعه أخوه السلطان المستقبلي أحمد المنصور الذهبي، ملكَ البرتغال سبستيان الأول، الذي دعمه السلطان المخلوع السابق المتوكل."),
 photo("ali-moussa", "ضريح سيدي علي بن موسى، في منطقة الريف الشرقي، بمدينة العروي."),
 p("وفي نهاية هذه المعركة، حقق جيش السلطان عبد الملك نصرًا كاملًا، أدى إلى مقتل الملك سبستيان الأول والسلطان الخائن المتوكل. وتسبب هذا النصر في نهاية الأسرة الحاكمة في البرتغال وضمّ البلاد إلى التاج الإسباني. وتمكن سيدي علي بن موسى من العودة إلى منطقته الأصلية، وتحديدًا العروي، حيث دُفن. ويقع ضريحه إلى جانب ضريح أبيه سيدي موسى بن علي في المقبرة التي تحمل اسمه عند مدخل المدينة."),
 p("ومنذ القرن السادس عشر، دُفن اثنا عشر جدًّا من أجداد الشيخ محمد فوزي الكركري في منطقة الريف الشرقي، بين العروي وتمسمان. وتشهد أضرحتهم التي تعلوها القباب على تجذّر هذه السلالة في المنطقة. وكان كثير منهم علماء في الفقه الإسلامي، وعارفين بالله أيضًا وأدلّاء على طريق التحقق الروحي."),
 p("وولد سيدي علي بن موسى مولاي محمد، الذي ولد مولاي العربي، الذي ولد مولاي أحمد، الذي ولد مولاي عبد القادر، الذي ولد الشيخ وقطب زمانه سيدي محمد بن القدور البوكيلي، الجد الخامس للشيخ محمد فوزي الكركري."),
]
